import unittest

from handoff_demo.expiry import is_expired


class HiddenTests(unittest.TestCase):
    def test_offsets_represent_instants_not_clock_labels(self):
        self.assertFalse(is_expired("2026-01-02T00:30:00+08:00", "2026-01-01T17:00:00+02:00"))
        self.assertTrue(is_expired("2026-01-02T00:30:00+08:00", "2026-01-01T12:31:00-04:00"))

    def test_inclusive_boundary_fractional_seconds_and_naive_utc(self):
        self.assertTrue(is_expired("2026-01-02T00:30:00+08:00", "2026-01-01T16:30:00+00:00"))
        self.assertFalse(is_expired("2026-01-01T16:30:00.500+00:00", "2026-01-01T16:30:00.499+00:00"))
        self.assertTrue(is_expired("2026-01-01T16:30:00", "2026-01-01T16:30:00+00:00"))


if __name__ == "__main__":
    unittest.main()
